lesson(ch, "fractions-half-quarter", "Halves and quarters", ["Say what a half and a quarter are.", "Find a half and a quarter of small numbers."],
  [("definition", "Half", "A **half** is one of two equal parts. We write 1/2. A cake cut into two equal parts gives two halves."),
   ("retenir", "Quarter", "A **quarter** is one of four equal parts. We write 1/4. Two quarters make a half. Four quarters make a whole."),
   ("pieges", "Common mistakes", "- The parts must be equal.\n- A quarter is smaller than a half.\n- Half of 10 is 5, not 2.")],
  [("Example 1", "Find half of 12 oranges.", ["Share 12 into 2 equal groups.", "12 ÷ 2 = 6."], "6", frac_circle(2, 1)),
   ("Example 2", "Find a quarter of 8 mangoes.", ["Share 8 into 4 equal groups.", "8 ÷ 4 = 2."], "2", frac_circle(4, 1))],
  (frac_bar(4, 1), "One part out of four: a quarter.", "A bar cut into four parts with one part coloured."),
  [("n", "Half of 10 is...", 5, "10 ÷ 2 = 5."), ("n", "A quarter of 20 is...", 5, "20 ÷ 4 = 5."), ("m", "Which picture shows a half? It has...", "2 equal parts, 1 coloured", ["4 equal parts, 1 coloured", "3 unequal parts", "no parts"], "A half is 1 of 2 equal parts.")],
  [("n", "Half of 18 is...", 9, "9."), ("t", "Two quarters make a half.", True, "2/4 = 1/2.")],
  ("p", "Mama has a loaf of bread and 16 buns.", [("n", "She cuts the loaf into 4 equal parts and gives 1 part to Bih. How many parts are left?", 3, "4 − 1 = 3."), ("n", "She gives half of the 16 buns to the school. How many buns?", 8, "16 ÷ 2 = 8.")]),
  [("Class 2 maths fractions: a half is...", "1 of 2 equal parts", ["1 of 4 equal parts", "2 of 3 parts", "1 of 10 parts"], "Half is 1/2."),
   ("Class 2 maths fractions: a quarter of 12 is...", "3", ["4", "6", "8"], "12 ÷ 4 = 3."),
   ("How many quarters make a whole?", "4", ["2", "3", "1"], "4."),
   ("Which is bigger: a half or a quarter?", "a half", ["a quarter", "the same", "none"], "Half is bigger."),
   ("Half of 6 is...", "3", ["2", "6", "12"], "3.")],
  ["Only 1/2 and 1/4 here; thirds are left for Class 3."], prereq=["class2-maths-division-sharing"])

