  [("n", "A table is 120 cm long. A bench is 150 cm long. How much longer is the bench?", 30, "150 − 120 = 30.", "cm"), ("t", "100 cm make 1 m.", True, "True.")],
  ("p", "A tailor in Bamenda has 5 m of cloth.", [("n", "She uses 2 m for a dress. How many metres are left?", 3, "5 − 2 = 3.", "m"), ("n", "How many cm is that? (3 m)", 300, "300 cm.", "cm")]),
